using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.Documents;
using Avalonia.Media;

namespace TheLadsLauncher.Controls;

/// <summary>
/// One Flaticon glyph (the StreamGeometry "Ico.&lt;kind&gt;" of Styles/Icons.axaml, generated by tools/icons/gen_icons.py) in the
/// inherited text colour, so it follows a button's hover and disabled colours like its label. A name without a glyph draws nothing.
/// <c>&lt;c:Glyph Kind="refresh" Size="14"/&gt;</c>, or <c>c:Ico.Name="refresh"</c> on a Button to put it before the button's text.
/// </summary>
public sealed class Glyph : Control
{
    /// <summary>The icon's side in the generated geometry's units.</summary>
    private const double Box = 300;

    public static readonly StyledProperty<string?> KindProperty = AvaloniaProperty.Register<Glyph, string?>(nameof(Kind));
    public static readonly StyledProperty<double> SizeProperty = AvaloniaProperty.Register<Glyph, double>(nameof(Size), 14);
    public static readonly StyledProperty<IBrush?> ForegroundProperty = TextElement.ForegroundProperty.AddOwner<Glyph>();

    private Geometry? _geometry;

    static Glyph()
    {
        AffectsRender<Glyph>(KindProperty, SizeProperty, ForegroundProperty);
        AffectsMeasure<Glyph>(SizeProperty);
        KindProperty.Changed.AddClassHandler<Glyph>((glyph, _) => glyph._geometry = null);
    }

    public string? Kind { get => GetValue(KindProperty); set => SetValue(KindProperty, value); }
    public double Size { get => GetValue(SizeProperty); set => SetValue(SizeProperty, value); }
    public IBrush? Foreground { get => GetValue(ForegroundProperty); set => SetValue(ForegroundProperty, value); }

    protected override Size MeasureOverride(Size availableSize) => new(Size, Size);

    protected override void OnAttachedToLogicalTree(Avalonia.LogicalTree.LogicalTreeAttachmentEventArgs e)
    {
        base.OnAttachedToLogicalTree(e);
        _geometry = null; // resolved against the tree it is in now
    }

    public override void Render(DrawingContext context)
    {
        if (Kind is not { Length: > 0 } kind) return;
        if (_geometry == null && this.TryFindResource("Ico." + kind, ActualThemeVariant, out var found)) _geometry = found as Geometry;
        if (_geometry == null || Foreground == null) return;
        using (context.PushTransform(Matrix.CreateScale(Size / Box, Size / Box)))
            context.DrawGeometry(Foreground, null, _geometry);
    }
}
